 function choose(k){state.starter=k;state.heroMax=mons[k].hp;state.heroHp=state.heroMax;state.party=[k];state.phase='battle';state.battle=1;state.enemy='vexlet';state.enemyMax=mons.vexlet.hp;state.enemyHp=state.enemyMax;$('#overlay').style.display='none';$('#hint').textContent='A WILD VEXLET APPEARED!';refresh();renderActions();setMessage(`Professor Juniper gave you ${mons[k].name}! A wild Vexlet leapt from the grass!`,'Your first battle begins · Choose FIGHT to see your moves');save();}

